"use client";

import * as React from "react";
import { ArrowRight, Check, Eye, EyeOff, RotateCcw } from "lucide-react";

type DivProps = React.ComponentProps<"div">;
type DivBase = { [key in keyof DivProps as key extends "onSubmit" | "onChange" | "defaultValue" ? never : key]: DivProps[key] };

export type SignUpStep = "email" | "name" | "password" | "terms";
export type SignUpStatus = "idle" | "submitting" | "error" | "done";
export type SignUpValues = { email: string; name: string; password: string; agreed: boolean };
export type SignUpPartialValues = { email?: string; name?: string; password?: string; agreed?: boolean };
export type SignUpRule = { id: string; label: React.ReactNode; test: (value: string) => boolean };
export type SignUpValidators = {
  /** Return null when valid, otherwise the help text shown after the field loses focus. */
  email?: (value: string) => string | null;
  name?: (value: string) => string | null;
  password?: (value: string, rules: SignUpRule[]) => string | null;
};
export type SignUpSocial = { label: React.ReactNode; onClick?: () => void };
export type SignUpLabels = {
  title?: React.ReactNode;
  subtitle?: React.ReactNode;
  signIn?: React.ReactNode;
  email?: React.ReactNode;
  name?: React.ReactNode;
  password?: React.ReactNode;
  terms?: React.ReactNode;
  emailPlaceholder?: string;
  namePlaceholder?: string;
  passwordPlaceholder?: string;
  emailHelp?: string;
  nameHelp?: string;
  passwordHelp?: string;
  termsHelp?: string;
  continue?: string;
  create?: string;
  submitting?: string;
  retry?: string;
  done?: string;
  welcome?: (firstName: string, values: SignUpValues) => React.ReactNode;
  next?: (values: SignUpValues) => React.ReactNode;
  open?: React.ReactNode;
  error?: string;
  socialDivider?: React.ReactNode;
  showPassword?: string;
  hidePassword?: string;
};

export type ProgressiveSignUpFormProps = DivBase & {
  /** Resolve to finish (the card turns into the welcome state); reject to show the retry state with the error message. */
  onSubmit: (values: SignUpValues) => unknown;
  /** Which fields appear, in order. Each one grows in once the previous field is valid. */
  steps?: SignUpStep[];
  validate?: SignUpValidators;
  passwordRules?: SignUpRule[];
  labels?: SignUpLabels;
  social?: SignUpSocial[];
  signInHref?: string;
  onSignIn?: () => void;
  termsHref?: string;
  privacyHref?: string;
  brand?: React.ReactNode;
  brandName?: string;
  values?: SignUpValues;
  defaultValues?: SignUpPartialValues;
  onValuesChange?: (values: SignUpValues) => void;
  onFieldChange?: (field: SignUpStep, value: string | boolean) => void;
  status?: SignUpStatus;
  onStatusChange?: (status: SignUpStatus) => void;
  /** Reports the newest field as it appears, then "done" when the welcome state is shown. */
  onStepChange?: (step: SignUpStep | "done") => void;
  /** The welcome state's button. */
  onComplete?: () => void;
  /** Pause after the last keystroke before the next field grows in. Enter reveals it at once. */
  revealDelay?: number;
  /** How long the submit button takes to fill most of the way while onSubmit is pending. */
  expectedMs?: number;
};

const EASE = "cubic-bezier(0.22, 1, 0.36, 1)";
const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
const FOCUS = "outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-card";
const INPUT = "h-11 w-full rounded-xl border border-border bg-background px-3.5 text-sm text-foreground outline-none transition-[border-color,box-shadow] duration-300 motion-reduce:transition-none placeholder:text-muted-foreground/60 focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/35 disabled:cursor-not-allowed";
const ALL_STEPS: SignUpStep[] = ["email", "name", "password", "terms"];
const STEP_NAMES = { email: "Email", name: "Name", password: "Password", terms: "Terms" };
const NO_SOCIAL: SignUpSocial[] = [];
const NO_LABELS: SignUpLabels = {};
const NO_VALIDATORS: SignUpValidators = {};

export const defaultPasswordRules: SignUpRule[] = [
  { id: "length", label: "8+ characters", test: (value) => value.length >= 8 },
  { id: "number", label: "Number", test: (value) => /\d/.test(value) },
  { id: "case", label: "Mixed case", test: (value) => /[a-z]/.test(value) && /[A-Z]/.test(value) },
  { id: "symbol", label: "Symbol", test: (value) => /[^A-Za-z0-9\s]/.test(value) },
];

const DEFAULT_LABELS = {
  title: "Create your account",
  subtitle: "Already have an account?",
  signIn: "Sign in",
  email: "Work email",
  name: "Full name",
  password: "Password",
  terms: "I agree to the Terms of Service and Privacy Policy",
  emailPlaceholder: "you@company.com",
  namePlaceholder: "Your name",
  passwordPlaceholder: "Create a password",
  emailHelp: "Enter a valid email, like name@company.com",
  nameHelp: "Enter at least two characters",
  passwordHelp: "Meet all four requirements",
  termsHelp: "Please accept the terms to continue",
  continue: "Continue",
  create: "Create account",
  submitting: "Creating account…",
  retry: "Try again",
  done: "Account created",
  welcome: (firstName: string) => `Welcome, ${firstName}`,
  next: (values: SignUpValues) => `We sent a confirmation link to ${values.email}.`,
  open: "Open workspace",
  error: "We couldn't create your account. Try again.",
  socialDivider: "or continue with",
  showPassword: "Show password",
  hidePassword: "Hide password",
};

export const isValidEmail = (value: string) => EMAIL.test(value.trim());

/** "Jordan Lee" → "Jordan"; falls back to the part of the email before the @ sign. */
export function firstNameOf(values: SignUpValues) {
  const fromName = values.name.trim().split(/\s+/)[0] ?? "";
  if (fromName) return fromName;
  const local = values.email.split("@")[0] ?? "";
  const word = local.split(/[._+-]/)[0] ?? "";
  return word ? word.charAt(0).toUpperCase() + word.slice(1).toLowerCase() : "there";
}

function useReducedMotion() {
  const [reduced, setReduced] = React.useState(true);
  React.useEffect(() => {
    const media = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => setReduced(media.matches);
    update();
    media.addEventListener("change", update);
    return () => media.removeEventListener("change", update);
  }, []);
  return reduced;
}

function DefaultMark() {
  return (
    <svg viewBox="0 0 20 20" aria-hidden="true" className="size-4" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round">
      <path d="M4.5 15.5C4.5 9.4 9.4 4.5 15.5 4.5c0 6.1-4.9 11-11 11Zm0 0 5.5-5.5" />
    </svg>
  );
}

function Reveal({ animate, innerClassName = "", children, ...rest }: React.ComponentProps<"div"> & { animate: boolean; innerClassName?: string }) {
  const outer = React.useRef(null as HTMLDivElement | null);
  const inner = React.useRef(null as HTMLDivElement | null);
  React.useLayoutEffect(() => {
    const box = outer.current;
    const content = inner.current;
    if (!box || !content || !animate || typeof box.animate !== "function") return;
    const height = content.getBoundingClientRect().height;
    box.dataset.entering = "true";
    box.style.overflow = "hidden";
    const grow = box.animate([{ height: "0px" }, { height: `${height}px` }], { duration: 240, easing: EASE });
    const rise = content.animate([{ opacity: 0, transform: "translateY(-6px) scale(0.985)" }, { opacity: 1, transform: "translateY(0) scale(1)" }], { duration: 240, easing: EASE });
    const settle = () => { box.style.overflow = ""; box.dataset.entering = "false"; };
    grow.onfinish = settle;
    return () => { grow.cancel(); rise.cancel(); settle(); };
  }, []);
  return (
    <div ref={outer} data-entering="false" {...rest}>
      <div ref={inner} className={innerClassName}>{children}</div>
    </div>
  );
}

function FadeUp({ children, ...rest }: React.ComponentProps<"div">) {
  const ref = React.useRef(null as HTMLDivElement | null);
  React.useLayoutEffect(() => {
    const node = ref.current;
    if (!node || typeof node.animate !== "function" || window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    const animation = node.animate([{ opacity: 0, transform: "translateY(14px)" }, { opacity: 1, transform: "translateY(0)" }], { duration: 420, delay: 40, easing: EASE, fill: "backwards" });
    return () => animation.cancel();
  }, []);
  return <div ref={ref} {...rest}>{children}</div>;
}

function Ghost({ text, onDone }: { text: string; onDone: () => void }) {
  const ref = React.useRef(null as HTMLSpanElement | null);
  React.useLayoutEffect(() => {
    const node = ref.current;
    if (!node || typeof node.animate !== "function") { onDone(); return; }
    const animation = node.animate([{ opacity: 1, transform: "translateY(0)" }, { opacity: 0, transform: "translateY(-10px)" }], { duration: 280, easing: EASE, fill: "forwards" });
    animation.onfinish = onDone;
    return () => animation.cancel();
  }, []);
  return <span ref={ref} data-ghost aria-hidden="true" className="absolute left-0 top-0 inline-block">{text}</span>;
}

function RollingLabel({ text, reduced }: { text: string; reduced: boolean }) {
  const stage = React.useRef(null as HTMLSpanElement | null);
  const widthAnimation = React.useRef(null as Animation | null);
  const width = React.useRef(0);
  const previous = React.useRef(text);
  const [ghost, setGhost] = React.useState(null as string | null);
  React.useLayoutEffect(() => {
    const node = stage.current;
    if (!node) return;
    widthAnimation.current?.cancel();
    const next = node.getBoundingClientRect().width;
    const from = width.current;
    const old = previous.current;
    width.current = next;
    previous.current = text;
    if (old === text || reduced || typeof node.animate !== "function") return;
    if (from > 0 && Math.abs(from - next) > 0.5) widthAnimation.current = node.animate([{ width: `${from}px` }, { width: `${next}px` }], { duration: 280, easing: EASE });
    node.querySelector("[data-label]")?.animate([{ opacity: 0, transform: "translateY(10px)" }, { opacity: 0.25, offset: 0.45 }, { opacity: 1, transform: "translateY(0)" }], { duration: 280, easing: EASE });
    setGhost(old);
  }, [text, reduced]);
  return (
    <span ref={stage} data-label-stage className="relative inline-block whitespace-nowrap align-middle leading-5" style={{ clipPath: "inset(0 -200px)" }}>
      <span key={text} data-label className="inline-block">{text}</span>
      {ghost !== null && <Ghost text={ghost} onDone={() => setGhost(null)} />}
    </span>
  );
}

export function ProgressiveSignUpForm({
  onSubmit,
  steps = ALL_STEPS,
  validate = NO_VALIDATORS,
  passwordRules = defaultPasswordRules,
  labels = NO_LABELS,
  social = NO_SOCIAL,
  signInHref,
  onSignIn,
  termsHref,
  privacyHref,
  brand,
  brandName,
  values: valuesProp,
  defaultValues,
  onValuesChange,
  onFieldChange,
  status: statusProp,
  onStatusChange,
  onStepChange,
  onComplete,
  revealDelay = 300,
  expectedMs = 1000,
  className = "",
  ref,
  ...rest
}: ProgressiveSignUpFormProps) {
  const reduced = useReducedMotion();
  const id = React.useId();
  const text = { ...DEFAULT_LABELS, ...labels };
  const title = labels.title ?? (brandName ? `Create your ${brandName} account` : DEFAULT_LABELS.title);
  const order = ALL_STEPS.filter((step) => steps.includes(step));
  const rules = passwordRules;
  const [localValues, setLocalValues] = React.useState({
    email: defaultValues?.email ?? "",
    name: defaultValues?.name ?? "",
    password: defaultValues?.password ?? "",
    agreed: defaultValues?.agreed ?? false,
  } as SignUpValues);
  const values = valuesProp ?? localValues;
  const [localStatus, setLocalStatus] = React.useState("idle" as SignUpStatus);
  const status = statusProp ?? localStatus;
  const [touched, setTouched] = React.useState([] as SignUpStep[]);
  const [attempted, setAttempted] = React.useState(false);
  const [shown, setShown] = React.useState(false);
  const [failure, setFailure] = React.useState("");
  const [announce, setAnnounce] = React.useState("");
  const [welcome, setWelcome] = React.useState(false);

  const passed = rules.filter((rule) => rule.test(values.password)).map((rule) => rule.id);
  const allPassed = rules.length === 0 ? values.password.length >= 8 : passed.length === rules.length;
  const errorOf = (step: SignUpStep): string | null => {
    if (step === "email") return validate.email ? validate.email(values.email) : isValidEmail(values.email) ? null : text.emailHelp;
    if (step === "name") return validate.name ? validate.name(values.name) : values.name.trim().length >= 2 ? null : text.nameHelp;
    if (step === "password") return validate.password ? validate.password(values.password, rules) : allPassed && values.password.length > 0 ? null : text.passwordHelp;
    return values.agreed ? null : text.termsHelp;
  };
  const complete = (step: SignUpStep) => errorOf(step) === null;

  const [revealed, setRevealed] = React.useState(() => {
    const first = order.findIndex((step) => !complete(step));
    return first === -1 ? Math.max(1, order.length) : Math.max(1, first + 1);
  });
  const initialRevealed = React.useRef(revealed);
  const previousRevealed = React.useRef(revealed);
  const pendingFocus = React.useRef(null as SignUpStep | null);
  const rootRef = React.useRef(null as HTMLDivElement | null);
  const bodyRef = React.useRef(null as HTMLDivElement | null);
  const bodyHeight = React.useRef(0);
  const bodyAnimation = React.useRef(null as Animation | null);
  const wasWelcome = React.useRef(welcome);
  const fillRef = React.useRef(null as HTMLSpanElement | null);
  const fillAnimation = React.useRef(null as Animation | null);
  const ringRef = React.useRef(null as HTMLSpanElement | null);
  const sweep = React.useRef(0);
  const wasAllPassed = React.useRef(allPassed);
  const previousPassed = React.useRef(passed);
  const request = React.useRef(0);
  const focusWelcome = React.useRef(false);

  const shownSteps = order.slice(0, revealed);
  const allRevealed = revealed >= order.length;
  const allComplete = order.every(complete);
  const firstIncomplete = order.findIndex((step) => !complete(step));
  const isBlocked = (index: number) => firstIncomplete !== -1 && index > firstIncomplete;
  const canReveal = !allRevealed && shownSteps.every(complete);
  const lastStep = order[revealed - 1] ?? null;
  const lastValue = lastStep === null ? null : lastStep === "terms" ? values.agreed : values[lastStep];
  const buttonLabel = status === "submitting" ? text.submitting : status === "done" ? text.done : status === "error" ? text.retry : allRevealed ? text.create : text.continue;
  const note = status === "error" ? failure || text.error : attempted && allRevealed && order.includes("terms") && !values.agreed ? text.termsHelp : "";
  const firstName = firstNameOf(values);

  const setRoot = (node: HTMLDivElement | null) => {
    rootRef.current = node;
    if (typeof ref === "function") ref(node);
    else if (ref) ref.current = node;
  };
  const changeStatus = (next: SignUpStatus) => {
    if (statusProp === undefined) setLocalStatus(next);
    onStatusChange?.(next);
  };
  const change = (step: SignUpStep, value: string | boolean) => {
    const next = step === "terms" ? { ...values, agreed: value === true } : { ...values, [step]: String(value) };
    if (valuesProp === undefined) setLocalValues(next);
    onValuesChange?.(next);
    onFieldChange?.(step, value);
    if (status === "error") changeStatus("idle");
  };
  const touch = (step: SignUpStep) => setTouched((current) => (current.includes(step) ? current : [...current, step]));
  const revealNext = () => setRevealed((count) => Math.min(order.length, count + 1));
  const focusStep = (step: SignUpStep) => {
    const node = rootRef.current?.querySelector(`[data-field="${step}"]`);
    if (node instanceof HTMLElement) node.focus({ preventScroll: true });
  };

  const submit = async (event: React.FormEvent) => {
    event.preventDefault();
    if (status === "submitting" || status === "done") return;
    if (!allRevealed || !allComplete) {
      setAttempted(true);
      setTouched((current) => [...current, ...shownSteps.filter((step) => !current.includes(step))]);
      if (canReveal) {
        pendingFocus.current = order[revealed] ?? null;
        revealNext();
        return;
      }
      const first = shownSteps.find((step) => !complete(step));
      if (first) focusStep(first);
      return;
    }
    const token = ++request.current;
    setFailure("");
    changeStatus("submitting");
    setAnnounce(text.submitting);
    try {
      await onSubmit(values);
      if (token !== request.current) return;
      focusWelcome.current = rootRef.current?.contains(document.activeElement) ?? false;
      changeStatus("done");
    } catch (error) {
      if (token !== request.current) return;
      const message = error instanceof Error && error.message ? error.message : text.error;
      setFailure(message);
      changeStatus("error");
      setAnnounce(message);
    }
  };

  React.useEffect(() => {
    if (!canReveal) return;
    const timer = window.setTimeout(revealNext, Math.max(0, revealDelay));
    return () => window.clearTimeout(timer);
  }, [canReveal, lastValue, revealDelay]);

  React.useEffect(() => {
    if (previousRevealed.current === revealed) return;
    previousRevealed.current = revealed;
    const step = order[revealed - 1];
    if (!step) return;
    setAnnounce(`${STEP_NAMES[step]} field added`);
    onStepChange?.(step);
  }, [revealed]);

  React.useLayoutEffect(() => {
    const step = pendingFocus.current;
    if (!step) return;
    pendingFocus.current = null;
    focusStep(step);
  }, [revealed]);

  React.useLayoutEffect(() => {
    const root = rootRef.current;
    const was = previousPassed.current;
    previousPassed.current = passed;
    const fresh = passed.filter((rule) => !was.includes(rule));
    if (!root || reduced || fresh.length === 0) return;
    const animations = fresh.map((rule, index) => root.querySelector(`[data-segment="${rule}"] [data-segment-fill]`)?.animate(
      [{ transform: "scaleX(0)" }, { transform: "scaleX(1)" }],
      { duration: 160, delay: index * 160, easing: EASE, fill: "backwards" },
    ));
    return () => animations.forEach((animation) => animation?.cancel());
  }, [passed.join(","), reduced]);

  React.useLayoutEffect(() => {
    const ring = ringRef.current;
    const became = allPassed && !wasAllPassed.current;
    wasAllPassed.current = allPassed;
    if (!ring) return;
    cancelAnimationFrame(sweep.current);
    if (!allPassed) { ring.dataset.state = "idle"; ring.style.setProperty("--sweep", "0%"); return; }
    if (!became || reduced) { ring.dataset.state = "complete"; ring.style.setProperty("--sweep", "100%"); return; }
    ring.dataset.state = "sweeping";
    const start = performance.now();
    const tick = (now: number) => {
      const t = Math.min(1, (now - start) / 520);
      const eased = 1 - (1 - t) ** 3;
      ring.style.setProperty("--sweep", t < 1 ? `${(eased * 100).toFixed(2)}%` : "100%");
      if (t < 1) sweep.current = requestAnimationFrame(tick);
      else ring.dataset.state = "complete";
    };
    sweep.current = requestAnimationFrame(tick);
  }, [allPassed, reduced]);

  React.useLayoutEffect(() => {
    const fill = fillRef.current;
    if (!fill) return;
    const current = getComputedStyle(fill).width;
    fillAnimation.current?.cancel();
    fillAnimation.current = null;
    const animate = !reduced && typeof fill.animate === "function";
    if (status === "submitting") {
      if (!animate) { fill.style.width = "100%"; return; }
      fill.style.width = "0%";
      fillAnimation.current = fill.animate([{ width: "0%" }, { width: "88%" }], { duration: Math.max(200, expectedMs), easing: "cubic-bezier(0.2, 0.7, 0.3, 1)", fill: "forwards" });
    } else if (status === "done") {
      if (!animate) { fill.style.width = "100%"; return; }
      fill.style.width = "100%";
      fillAnimation.current = fill.animate([{ width: current }, { width: "100%" }], { duration: 220, easing: EASE });
    } else fill.style.width = "0%";
  }, [status, reduced, expectedMs]);

  React.useEffect(() => {
    if (status !== "done") { setWelcome(false); return; }
    setAnnounce(`Account created. Welcome, ${firstName}.`);
    if (reduced) { setWelcome(true); return; }
    const timer = window.setTimeout(() => setWelcome(true), 560);
    return () => window.clearTimeout(timer);
  }, [status, reduced]);

  React.useEffect(() => { if (welcome) onStepChange?.("done"); }, [welcome]);

  React.useLayoutEffect(() => {
    if (!welcome || !focusWelcome.current) return;
    focusWelcome.current = false;
    const heading = rootRef.current?.querySelector("[data-welcome] h2");
    if (heading instanceof HTMLElement) heading.focus({ preventScroll: true });
  }, [welcome]);

  React.useLayoutEffect(() => {
    const body = bodyRef.current;
    if (!body) return;
    const changed = wasWelcome.current !== welcome;
    wasWelcome.current = welcome;
    if (bodyAnimation.current && bodyAnimation.current.playState === "running") return;
    const height = body.getBoundingClientRect().height;
    const previous = bodyHeight.current;
    bodyHeight.current = height;
    if (!changed || !previous || reduced || typeof body.animate !== "function" || Math.abs(previous - height) < 1) return;
    body.style.overflow = "hidden";
    const animation = body.animate([{ height: `${previous}px` }, { height: `${height}px` }], { duration: 420, easing: EASE });
    bodyAnimation.current = animation;
    animation.onfinish = () => { body.style.overflow = ""; bodyAnimation.current = null; };
  });

  React.useEffect(() => () => {
    request.current += 1;
    cancelAnimationFrame(sweep.current);
    fillAnimation.current?.cancel();
    bodyAnimation.current?.cancel();
  }, []);

  const helpFor = (step: SignUpStep, index: number) => (touched.includes(step) && !isBlocked(index) ? errorOf(step) : null);
  const termsLabel = labels.terms ?? (termsHref || privacyHref ? (
    <>
      I agree to the{" "}
      {termsHref ? <a href={termsHref} className={`font-medium text-foreground underline-offset-2 hover:underline ${FOCUS} rounded-sm`}>Terms of Service</a> : "Terms of Service"} and{" "}
      {privacyHref ? <a href={privacyHref} className={`font-medium text-foreground underline-offset-2 hover:underline ${FOCUS} rounded-sm`}>Privacy Policy</a> : "Privacy Policy"}
    </>
  ) : DEFAULT_LABELS.terms);

  const renderField = (step: SignUpStep, index: number) => {
    const blocked = isBlocked(index);
    const help = helpFor(step, index);
    if (step === "terms") {
      return (
        <label className={`flex items-start gap-2.5 text-[12.5px] leading-5 text-muted-foreground ${blocked ? "cursor-not-allowed" : "cursor-pointer"}`}>
          <span className="relative mt-0.5 flex size-4 shrink-0">
            <input
              type="checkbox"
              name="terms"
              data-field="terms"
              checked={values.agreed}
              disabled={blocked}
              aria-invalid={help ? true : undefined}
              onChange={(event) => change("terms", event.target.checked)}
              onBlur={() => touch("terms")}
              className={`peer size-4 cursor-[inherit] appearance-none rounded-[5px] border border-muted-foreground/50 bg-background transition-colors duration-200 motion-reduce:transition-none checked:border-primary checked:bg-primary ${FOCUS}`}
            />
            <Check className="pointer-events-none absolute inset-0 m-auto size-3 text-primary-foreground opacity-0 transition-opacity duration-200 motion-reduce:transition-none peer-checked:opacity-100" strokeWidth={3} aria-hidden="true" />
          </span>
          <span>{termsLabel}</span>
        </label>
      );
    }
    const fieldId = `${id}-${step}`;
    const helpId = `${fieldId}-help`;
    return (
      <>
        <label htmlFor={fieldId} className="mb-1 block text-xs font-medium leading-4">{text[step]}</label>
        {step === "password" ? (
          <>
            <div className="relative">
              <input
                id={fieldId}
                name="password"
                data-field="password"
                type={shown ? "text" : "password"}
                autoComplete="new-password"
                autoCapitalize="off"
                spellCheck={false}
                placeholder={text.passwordPlaceholder}
                value={values.password}
                disabled={blocked}
                aria-invalid={help ? true : undefined}
                aria-describedby={helpId}
                onChange={(event) => change("password", event.target.value)}
                onBlur={() => touch("password")}
                className={`${INPUT} pr-11 ${allPassed ? "border-transparent" : ""}`}
              />
              <span
                ref={ringRef}
                data-ring
                data-state="idle"
                aria-hidden="true"
                style={{ "--sweep": "0%", background: "conic-gradient(from -90deg, var(--color-chart-2) 0 var(--sweep), transparent var(--sweep) 100%)", WebkitMask: "linear-gradient(black 0 0) content-box, linear-gradient(black 0 0)", mask: "linear-gradient(black 0 0) content-box, linear-gradient(black 0 0)", WebkitMaskComposite: "xor", maskComposite: "exclude", padding: 1.5 } as React.CSSProperties}
                className="pointer-events-none absolute inset-0 rounded-xl"
              />
              <button
                type="button"
                data-toggle-password
                aria-label={shown ? text.hidePassword : text.showPassword}
                aria-pressed={shown}
                disabled={blocked}
                onClick={() => setShown((current) => !current)}
                className={`absolute right-1.5 top-1/2 flex size-8 -translate-y-1/2 items-center justify-center rounded-lg text-muted-foreground transition-colors motion-reduce:transition-none hover:text-foreground disabled:cursor-not-allowed ${FOCUS}`}
              >
                {shown ? <EyeOff className="size-4" aria-hidden="true" /> : <Eye className="size-4" aria-hidden="true" />}
              </button>
            </div>
            <div
              id={helpId}
              data-meter
              role="meter"
              aria-label="Password strength"
              aria-valuemin={0}
              aria-valuemax={rules.length}
              aria-valuenow={passed.length}
              aria-valuetext={`${passed.length} of ${rules.length} requirements met`}
              className="mt-2 grid gap-1.5"
              style={{ gridTemplateColumns: `repeat(${Math.max(1, rules.length)}, minmax(0, 1fr))` }}
            >
              {rules.map((rule) => {
                const on = passed.includes(rule.id);
                return (
                  <span key={rule.id} data-segment={rule.id} data-on={on ? "true" : "false"} className="min-w-0">
                    <span className="block h-1 overflow-hidden rounded-full bg-muted">
                      <span data-segment-fill className="block h-full origin-left rounded-full bg-chart-2" style={{ transform: `scaleX(${on ? 1 : 0})` }} />
                    </span>
                    <span data-rule-label className={`mt-1 block truncate text-[10.5px] leading-3 transition-colors duration-200 motion-reduce:transition-none ${on ? "text-foreground" : "text-muted-foreground"}`}>{rule.label}</span>
                  </span>
                );
              })}
            </div>
          </>
        ) : (
          <>
            <input
              id={fieldId}
              name={step}
              data-field={step}
              type={step === "email" ? "email" : "text"}
              inputMode={step === "email" ? "email" : "text"}
              autoComplete={step === "email" ? "email" : "name"}
              autoCapitalize={step === "email" ? "off" : "words"}
              spellCheck={false}
              placeholder={step === "email" ? text.emailPlaceholder : text.namePlaceholder}
              value={values[step]}
              disabled={blocked}
              aria-invalid={help ? true : undefined}
              aria-describedby={helpId}
              onChange={(event) => change(step, event.target.value)}
              onBlur={() => touch(step)}
              className={INPUT}
            />
            <p id={helpId} data-help={step} className="mt-1 min-h-[14px] text-[11px] leading-[14px] text-muted-foreground">{help}</p>
          </>
        )}
      </>
    );
  };

  return (
    <div
      ref={setRoot}
      {...rest}
      data-slot="progressive-sign-up-form"
      data-status={status}
      data-phase={welcome ? "welcome" : "form"}
      data-revealed={revealed}
      data-complete={allComplete ? "true" : "false"}
      className={`w-full max-w-[420px] rounded-2xl bg-card p-5 text-card-foreground shadow-sm ring-1 ring-border ${className}`}
    >
      <div className="flex items-center justify-between gap-3">
        <span data-brand aria-hidden="true" className="flex size-7 shrink-0 items-center justify-center rounded-lg bg-primary text-primary-foreground">{brand ?? <DefaultMark />}</span>
        {!welcome && (
          <span className="text-[12px] leading-4 text-muted-foreground">
            {text.subtitle}{" "}
            {onSignIn && !signInHref ? (
              <button type="button" data-sign-in onClick={onSignIn} className={`rounded-sm font-medium text-foreground underline-offset-4 hover:underline ${FOCUS}`}>{text.signIn}</button>
            ) : (
              <a data-sign-in href={signInHref ?? "#"} onClick={onSignIn} className={`rounded-sm font-medium text-foreground underline-offset-4 hover:underline ${FOCUS}`}>{text.signIn}</a>
            )}
          </span>
        )}
      </div>

      <div ref={bodyRef} data-body>
        {welcome ? (
          <FadeUp data-welcome className="pt-4">
            <span data-welcome-check className="flex size-10 items-center justify-center rounded-full bg-chart-2/15 text-chart-2"><Check className="size-5" strokeWidth={2.5} aria-hidden="true" /></span>
            <h2 tabIndex={-1} className="mt-4 text-[18px] font-semibold leading-6 tracking-tight outline-none">{text.welcome(firstName, values)}</h2>
            <p data-next className="mt-1.5 text-[13px] leading-5 text-muted-foreground">{text.next(values)}</p>
            <button type="button" data-open onClick={onComplete} className={`mt-5 flex h-11 w-full items-center justify-center gap-2 rounded-xl bg-primary px-4 text-sm font-medium text-primary-foreground transition-colors duration-300 motion-reduce:transition-none hover:bg-primary/90 ${FOCUS}`}>
              {text.open}<ArrowRight className="size-4" aria-hidden="true" />
            </button>
          </FadeUp>
        ) : (
          <form data-form noValidate onSubmit={submit} aria-busy={status === "submitting" || undefined} aria-labelledby={`${id}-title`} className="pt-3">
            <h2 id={`${id}-title`} className="text-[18px] font-semibold leading-6 tracking-tight">{title}</h2>
            <div data-fields className="mt-4">
              {shownSteps.map((step, index) => (
                <Reveal
                  key={step}
                  data-step={step}
                  data-blocked={isBlocked(index) ? "true" : "false"}
                  animate={index >= initialRevealed.current && !reduced}
                  innerClassName={index === 0 ? "" : "pt-3"}
                  className={`transition-opacity duration-300 motion-reduce:transition-none ${isBlocked(index) ? "opacity-50" : "opacity-100"}`}
                >
                  {renderField(step, index)}
                </Reveal>
              ))}
            </div>
            <button
              type="submit"
              data-submit
              data-button-state={status === "idle" ? (allRevealed ? "create" : "continue") : status}
              disabled={status === "submitting" || status === "done"}
              aria-busy={status === "submitting" || undefined}
              className={`relative mt-4 flex h-11 w-full items-center justify-center overflow-hidden rounded-xl bg-primary px-4 text-sm font-medium text-primary-foreground transition-colors duration-300 motion-reduce:transition-none hover:bg-primary/90 disabled:cursor-default ${FOCUS}`}
            >
              <span ref={fillRef} data-fill aria-hidden="true" className="pointer-events-none absolute inset-y-0 left-0 bg-chart-2" style={{ width: "0%" }} />
              <span className="relative flex items-center gap-2">
                {status === "done" && <Check className="size-4" strokeWidth={2.5} aria-hidden="true" />}
                {status === "error" && <RotateCcw className="size-3.5" aria-hidden="true" />}
                <RollingLabel text={buttonLabel} reduced={reduced} />
                {status === "idle" && <ArrowRight className="size-4" aria-hidden="true" />}
              </span>
            </button>
            <p data-note data-note-kind={status === "error" ? "error" : note ? "terms" : "none"} className={`mt-1.5 min-h-[14px] text-center text-[11px] leading-[14px] ${status === "error" ? "text-foreground" : "text-muted-foreground"}`}>{note}</p>
            {social.length > 0 && (
              <>
                <div className="mt-3 flex items-center gap-3" aria-hidden="true">
                  <span className="h-px flex-1 bg-border" /><span className="text-[11px] leading-4 text-muted-foreground">{text.socialDivider}</span><span className="h-px flex-1 bg-border" />
                </div>
                <div data-social-row className={`mt-3 grid gap-2 ${social.length > 1 ? "grid-cols-2" : "grid-cols-1"}`}>
                  {social.map((item, index) => (
                    <button key={index} type="button" data-social onClick={item.onClick} className={`h-9 truncate rounded-xl border border-border bg-card px-3 text-[12.5px] font-medium text-foreground transition-colors duration-200 motion-reduce:transition-none hover:bg-muted ${FOCUS}`}>
                      {item.label}
                    </button>
                  ))}
                </div>
              </>
            )}
          </form>
        )}
      </div>
      <p role="status" aria-live="polite" aria-atomic="true" className="sr-only">{announce}</p>
    </div>
  );
}

export default ProgressiveSignUpForm;

